import net.minecraft.world.level.block.state.BlockState;
/** Independent native mechanics, routes and save witness for the jungle replacement. */
public final class JungleReplacementQualification {
 private static final com.google.gson.Gson GSON=new com.google.gson.GsonBuilder().setPrettyPrinting().create();
 private static final Set<String> MASONRY=Set.of("minecraft:cobblestone","minecraft:mossy_cobblestone","minecraft:stone_bricks","minecraft:mossy_stone_bricks","minecraft:cracked_stone_bricks","minecraft:chiseled_stone_bricks");
 private static final Map<BlockPos,com.google.gson.JsonObject> anatomy=new HashMap<>();
 private static final Map<BlockPos,String> preMechanics=new HashMap<>(),expectedEdits=new HashMap<>();
 private static int stage,ticks,firstAmmo,secondAmmo,arrows;private static ServerLevel level;private static ReimaginedLayoutPiece piece;private static Path dir;private static ServerPlayer player;private static boolean reopen;private static Map<String,Object> report;private static List<ChestBlockEntity> chests;private static List<DispenserBlockEntity> dispensers;private static final List<Object> interactions=new ArrayList<>();
 public static Map<String,Object> tick(ServerLevel l,ReimaginedLayoutPiece p,Path d,boolean r)throws Exception {
  if(stage==0){level=l;piece=p;dir=d;reopen=r;player=l.getServer().getPlayerList().getPlayers().getFirst();report=verify(l,p,d,r);if(Boolean.TRUE.equals(report.get("legacy"))){stage=99;return report;}if(r){saved();stage=99;return report;}for(int y=-5;y<=12;y++)for(int z=0;z<=14;z++)for(int x=0;x<=11;x++)preMechanics.put(new BlockPos(x,y,z),normalized(l.getBlockState(p.local(x,y,z))));stage=1;}
  ticks++;arrows=Math.max(arrows,level.getEntitiesOfClass(net.minecraft.world.entity.projectile.arrow.AbstractArrow.class,net.minecraft.world.phys.AABB.of(piece.getBoundingBox())).size());
  if(stage==1){
   var loot=new ArrayList<Object>();for(var chest:chests){require(chest.getLootTable()!=null,"Original native chest loot table");String table=chest.getLootTable().identifier().toString();player.setPos(chest.getBlockPos().getX()+.5,chest.getBlockPos().getY()+.1,chest.getBlockPos().getZ()-1.5);player.gameMode.useItemOn(player,level,net.minecraft.world.item.ItemStack.EMPTY,net.minecraft.world.InteractionHand.MAIN_HAND,new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atCenterOf(chest.getBlockPos()),net.minecraft.core.Direction.UP,chest.getBlockPos(),false));require(chest.getLootTable()==null,"Actual chest interaction unpacks native loot");int before=count(chest);require(before>0,"Native loot populated");for(int slot=0;slot<chest.getContainerSize();slot++)player.containerMenu.clicked(slot,0,net.minecraft.world.inventory.ContainerInput.QUICK_MOVE,player);require(count(chest)==0,"Actual menu transfers native loot to player inventory");player.closeContainer();loot.add(Map.of("position",List.of(chest.getBlockPos().getX(),chest.getBlockPos().getY(),chest.getBlockPos().getZ()),"lootTable",table,"itemsTransferred",before));}
   report.put("nativeChestInteractions",loot);for(var dispenser:dispensers){require(dispenser.getLootTable()!=null,"Native dispenser loot table");dispenser.unpackLootTable(null);}firstAmmo=ammo(9,-2,3);secondAmmo=ammo(3,-2,1);require(firstAmmo>0&&secondAmmo>0,"Both native arrow traps loaded");move(7,-3,3);stage=2;ticks=0;
  }else if(stage==2&&ticks>=14){require(ammo(9,-2,3)<firstAmmo,"Actual player tripwire fires first native dispenser");interactions.add(Map.of("trap",0,"before",firstAmmo,"after",ammo(9,-2,3)));move(3,-3,8);stage=3;ticks=0;
  }else if(stage==3&&ticks>=14){require(ammo(3,-2,1)<secondAmmo,"Actual player tripwire fires second native dispenser");interactions.add(Map.of("trap",1,"before",secondAmmo,"after",ammo(3,-2,1)));move(9,-3,13);lever(8);lever(10);stage=4;ticks=0;
  }else if(stage==4&&ticks>=12){int extended=0,heads=0;for(int y=-4;y<=0;y++)for(int z=7;z<=11;z++)for(int x=7;x<=11;x++){var state=level.getBlockState(piece.local(x,y,z));if(state.is(Blocks.STICKY_PISTON)&&state.getValue(net.minecraft.world.level.block.piston.PistonBaseBlock.EXTENDED))extended++;if(state.is(Blocks.PISTON_HEAD))heads++;}require(heads>0,"Native puzzle creates physical piston heads");report.put("leverPuzzlePistonHeads",heads);require(extended>0,"Actual native lever puzzle moves original pistons");report.put("leverPuzzleExtendedPistons",extended);lever(8);lever(10);stage=5;ticks=0;
  }else if(stage==5&&ticks>=18){move(6,1,5);mechanicsWitness();report.put("nativeTrapInteractions",interactions);report.put("maximumObservedNativeArrows",arrows);level.setBlock(piece.local(-13,-8,-4),Blocks.OAK_PLANKS.defaultBlockState(),3);saved();stage=99;return report;}
  return null;
 }
 private static void move(int x,int y,int z){var at=piece.local(x,y,z);level.getServer().getCommands().performPrefixedCommand(level.getServer().createCommandSourceStack(),"tp "+player.getName().getString()+" "+(at.getX()+.5)+" "+(at.getY()+.02)+" "+(at.getZ()+.5));player.setDeltaMovement(net.minecraft.world.phys.Vec3.ZERO);}
 private static void lever(int x){var at=piece.local(x,-2,12);player.gameMode.useItemOn(player,level,net.minecraft.world.item.ItemStack.EMPTY,net.minecraft.world.InteractionHand.MAIN_HAND,new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atCenterOf(at),net.minecraft.core.Direction.NORTH,at,false));}
 private static int ammo(int x,int y,int z){return count((DispenserBlockEntity)level.getBlockEntity(piece.local(x,y,z)));}
 private static List<Object> items(net.minecraft.world.Container c){var list=new ArrayList<Object>();var ops=net.minecraft.resources.RegistryOps.create(com.mojang.serialization.JsonOps.INSTANCE,level.registryAccess());for(int i=0;i<c.getContainerSize();i++){var stack=c.getItem(i);if(!stack.isEmpty())list.add(Map.of("slot",i,"item",net.minecraft.world.item.ItemStack.CODEC.encodeStart(ops,stack).getOrThrow()));}return list;}
 private static int count(net.minecraft.world.Container c){int n=0;for(int i=0;i<c.getContainerSize();i++)n+=c.getItem(i).getCount();return n;}
 private static void saved()throws Exception {var marker=dir.resolve("native-player-witness.json");var witness=Map.of("uuid",player.getUUID().toString(),"inventoryItems",count(player.getInventory()),"inventory",items(player.getInventory()),"repair",level.getBlockState(piece.local(-13,-8,-4)).toString(),"emptyChests",chests.stream().filter(c->c.getLootTable()==null&&count(c)==0).count(),"trapAmmo",List.of(ammo(9,-2,3),ammo(3,-2,1)),"trapInventory",List.of(items((DispenserBlockEntity)level.getBlockEntity(piece.local(9,-2,3))),items((DispenserBlockEntity)level.getBlockEntity(piece.local(3,-2,1)))));
  if(reopen){var old=com.google.gson.JsonParser.parseString(Files.readString(marker));require(GSON.toJsonTree(witness).equals(old),"Native player UUID/inventory, consumed chests/ammo and repair persist exactly");}else Files.writeString(marker,GSON.toJson(witness));report.put("playerSaveWitness",witness);}
 private static Map<String,Object> verify(ServerLevel l,ReimaginedLayoutPiece p,Path d,boolean r)throws Exception {
  var result=new LinkedHashMap<String,Object>();chests=new ArrayList<>();dispensers=new ArrayList<>();int levers=0,pistons=0;
  for(int y=-5;y<=12;y++)for(int z=0;z<=14;z++)for(int x=0;x<=11;x++){var at=p.local(x,y,z);var s=l.getBlockState(at);var be=l.getBlockEntity(at);if(be instanceof ChestBlockEntity c)chests.add(c);if(be instanceof DispenserBlockEntity c)dispensers.add(c);if(s.is(Blocks.LEVER))levers++;if(s.is(Blocks.STICKY_PISTON))pistons++;}
  require(chests.size()==2&&dispensers.size()==2&&levers==3&&pistons==3,"Native2chests/2dispensers/3levers/3sticky pistons");result.put("routeNodes",ReimaginedRoutes.verify(l,p));result.put("chests",chests.size());result.put("dispensers",dispensers.size());result.put("levers",levers);result.put("stickyPistons",pistons);
  var tag=p.createTag(net.minecraft.world.level.levelgen.structure.pieces.StructurePieceSerializationContext.fromLevel(l));boolean legacy=tag.getIntOr("JungleReplacement",0)==0;result.put("legacy",legacy);result.put("replacementDefinition",tag.getIntOr("JungleReplacement",0));
  String reference=System.getProperty("blockbranch.jungleReplacementReference","");require(!reference.isEmpty(),"Explicit authentic172 anatomy reference");if(r&&!legacy){require(Files.exists(d.resolve("native-puzzle-edits.json")),"Explicit saved puzzle edit witness");for(var value:com.google.gson.JsonParser.parseString(Files.readString(d.resolve("native-puzzle-edits.json"))).getAsJsonArray()){var edit=value.getAsJsonObject();var at=edit.getAsJsonArray("local");var pos=new BlockPos(at.get(0).getAsInt(),at.get(1).getAsInt(),at.get(2).getAsInt());require(puzzleCell(pos),"Saved edit inside original piston puzzle only");expectedEdits.put(pos,edit.get("after").getAsString());}}int protectedCells=0,towerCells=0,masonry=0,coffers=0,niches=0;var lines=Files.readAllLines(Path.of(reference).resolve("native-site.voxels.jsonl"));for(String line:lines){var row=com.google.gson.JsonParser.parseString(line).getAsJsonObject();anatomy.put(new BlockPos(row.get("x").getAsInt(),row.get("y").getAsInt(),row.get("z").getAsInt()),row);}for(String line:lines){var row=com.google.gson.JsonParser.parseString(line).getAsJsonObject();int x=row.get("x").getAsInt(),y=row.get("y").getAsInt(),z=row.get("z").getAsInt();boolean core=x>=0&&x<=11&&z>=0&&z<=14&&y>=-5&&y<=12;boolean tower=(x>=-12&&x<=-6&&z>=-3&&z<=3&&y>=0&&y<21)||(x>=17&&x<=23&&z>=14&&z<=20&&y>=0&&y<27);if(!legacy&&!core&&!tower)continue;String old=row.get("state").getAsString();var at=p.local(x,y,z);var actual=l.getBlockState(at);String value=JungleStoneworkQualification.architecturalState(actual).toString();var savedEdit=expectedEdits.get(new BlockPos(x,y,z));if(!legacy&&savedEdit!=null){require(savedEdit.equals(value),"Exact explicit native puzzle edit persists "+x+","+y+","+z);protectedCells++;continue;}boolean full=MASONRY.stream().anyMatch(id->old.equals("Block{"+id+"}"));if(legacy){require(old.equals(value),"Authentic172 adopted full-site exact "+x+","+y+","+z);protectedCells++;continue;}if(full){boolean nowFull=MASONRY.contains(net.minecraft.core.registries.BuiltInRegistries.BLOCK.getKey(actual.getBlock()).toString())&&actual.isCollisionShapeFullBlock(l,at)&&actual.getLightEmission()==0&&actual.getFluidState().isEmpty();boolean coffer=core&&y>=3&&Math.floorMod(x,3)==1&&Math.floorMod(z,3)==1&&actual.is(Blocks.MOSSY_STONE_BRICK_SLAB)&&actual.getValue(net.minecraft.world.level.block.SlabBlock.TYPE)==net.minecraft.world.level.block.state.properties.SlabType.TOP&&oldMasonry(x,y+1,z)&&anatomy.get(new BlockPos(x,y-1,z)).get("state").getAsString().equals("Block{minecraft:air}")&&l.getBlockState(at.above()).isCollisionShapeFullBlock(l,at.above())&&actual.getFluidState().isEmpty()&&actual.getLightEmission()==0;boolean niche=core&&niche(l,p,actual,x,y,z);if(coffer)coffers++;if(niche)niches++;require(nowFull||coffer||niche,"Only full opaque masonry or validated backed native relief "+x+","+y+","+z+" "+actual);masonry++;}else if(!core&&actual.isAir()&&(old.equals("Block{minecraft:air}")||old.equals("Block{minecraft:cave_air}"))){require(actual.is(Blocks.AIR)||actual.is(Blocks.CAVE_AIR),"Tower air variant only");}else require(old.equals(value),"Exact native nonmasonry/mechanism or tower interior "+x+","+y+","+z+" old="+old+" actual="+value);if(core)protectedCells++;else towerCells++;}
  if(!legacy){var walk=ReimaginedRoutes.class.getDeclaredMethod("walk",ServerLevel.class,net.minecraft.world.level.levelgen.structure.BoundingBox.class,List.class,boolean.class);walk.setAccessible(true);result.put("newShrineRouteNodes",walk.invoke(null,l,p.getBoundingBox(),List.of(p.local(-9,0,0),p.local(5,19,10),p.local(5,19,16),p.local(5,19,20)),true));}
  result.put("codec",PyramidGalleryQualification.class.getMethod("codec",ServerLevel.class).invoke(null,l));result.put("backedNativeCoffers",coffers);result.put("closedBackNativeNiches",niches);result.put("nativeProtectedCells",protectedCells);result.put("towerInteriorCells",towerCells);result.put("equivalentMasonryCells",masonry);return result;
 }
 private static String normalized(BlockState state){return JungleStoneworkQualification.architecturalState(state).toString();}
 private static boolean puzzleCell(BlockPos p){return p.getX()>=7&&p.getX()<=11&&p.getY()>=-3&&p.getY()<=0&&p.getZ()>=7&&p.getZ()<=11;}
 private static void mechanicsWitness()throws Exception {var edits=new ArrayList<Object>();for(var entry:preMechanics.entrySet()){var pos=entry.getKey();var state=level.getBlockState(piece.local(pos.getX(),pos.getY(),pos.getZ()));String now=normalized(state);if(now.equals(entry.getValue()))continue;require(puzzleCell(pos),"No persistent block edits outside original native piston puzzle "+pos+" "+entry.getValue()+" -> "+now);require(!state.is(Blocks.MOVING_PISTON),"Native puzzle settles before save");edits.add(Map.of("local",List.of(pos.getX(),pos.getY(),pos.getZ()),"before",entry.getValue(),"after",now));}Files.writeString(dir.resolve("native-puzzle-edits.json"),GSON.toJson(edits));report.put("explicitNativePuzzleEdits",edits);}
 private static boolean niche(ServerLevel l,ReimaginedLayoutPiece p,BlockState now,int x,int y,int z){
  if(y!=1&&y!=2)return false;int dx=0,dz=0;
  if((x==2||x==9)&&(z==4||z==5||z==7||z==8))dx=x==2?-1:1;
  else if((z==2||z==12)&&(x==3||x==8))dz=z==2?-1:1;else return false;
  if(!now.is(Blocks.MOSSY_STONE_BRICK_STAIRS)||now.getValue(net.minecraft.world.level.block.StairBlock.HALF)!=net.minecraft.world.level.block.state.properties.Half.TOP||!now.getFluidState().isEmpty()||now.getLightEmission()!=0||!oldMasonry(x,y+1,z)||!oldMasonry(x,y-1,z))return false;
  var at=p.local(x,y,z);var outward=p.local(x+dx,y,z+dz).subtract(at);var face=outward.getX()>0?net.minecraft.core.Direction.EAST:outward.getX()<0?net.minecraft.core.Direction.WEST:outward.getZ()>0?net.minecraft.core.Direction.SOUTH:net.minecraft.core.Direction.NORTH;
  if(now.getValue(net.minecraft.world.level.block.StairBlock.FACING)!=face)return false;
  var shape=now.getCollisionShape(l,at);return !net.minecraft.world.phys.shapes.Shapes.joinIsNotEmpty(shape,net.minecraft.world.phys.shapes.Shapes.block(),net.minecraft.world.phys.shapes.BooleanOp.ONLY_FIRST)&&!net.minecraft.world.phys.shapes.Shapes.joinIsNotEmpty(shape.getFaceShape(face),net.minecraft.world.phys.shapes.Shapes.block(),net.minecraft.world.phys.shapes.BooleanOp.NOT_SAME);
 }
 private static boolean oldMasonry(int x,int y,int z){var old=anatomy.get(new BlockPos(x,y,z));return old!=null&&MASONRY.stream().anyMatch(id->old.get("state").getAsString().equals("Block{"+id+"}"));}
 private static void require(boolean value,String message){if(!value)throw new AssertionError(message);}
}
